<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/src/bootstrap.php';
session_name('raiz_admin');
session_set_cookie_params(['httponly'=>true,'secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off','samesite'=>'Lax']);
session_start();
$token=$_SESSION['csrf']??=bin2hex(random_bytes(24));$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($token,(string)($_POST['csrf']??''))){http_response_code(403);exit('Solicitação inválida');}
 if(isset($_POST['logout'])){$_SESSION=[];session_destroy();header('Location: /admin/');exit;}
 $email=trim((string)($_POST['email']??''));$pass=(string)($_POST['password']??'');
 $q=\App\Db::pdo()->prepare('SELECT id,password_hash FROM admins WHERE email=? LIMIT 1');$q->execute([$email]);$user=$q->fetch();
 if($user && password_verify($pass,$user['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$user['id'];header('Location: /admin/');exit;}
 $error='Credenciais inválidas';
}
header('Content-Type: text/html; charset=utf-8');
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Painel — Raiz & Brasa</title><link rel="stylesheet" href="/assets/app.css"></head><body><header><a class="brand" href="/">Raiz & Brasa</a><nav><a href="/">Voltar ao site</a></nav></header><main class="wrap section"><h1>Painel do restaurante</h1><?php if(!isset($_SESSION['admin_id'])): ?><div class="panel" style="max-width:430px"><h2>Acesso restrito</h2><?php if($error):?><p role="alert"><?=h($error)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=h($token)?>"><label>E-mail<input type="email" name="email" required></label><label>Senha<input type="password" name="password" required></label><button>Entrar</button></form><p class="muted">Crie o usuário administrador conforme a documentação.</p></div><?php else: ?><?php $db=\App\Db::pdo();$stats=['orders'=>(int)$db->query("SELECT COUNT(*) FROM orders")->fetchColumn(),'reservations'=>(int)$db->query("SELECT COUNT(*) FROM reservations")->fetchColumn(),'revenue'=>(int)$db->query("SELECT COALESCE(SUM(total_cents),0) FROM orders WHERE payment_status='paid'")->fetchColumn()];$orders=$db->query("SELECT id,customer_name,fulfillment,total_cents,status,payment_status,created_at FROM orders ORDER BY id DESC LIMIT 20")->fetchAll();$reservations=$db->query("SELECT r.id,r.customer_name,r.guests,r.status,s.date,s.time FROM reservations r JOIN reservation_slots s ON s.id=r.slot_id ORDER BY r.id DESC LIMIT 20")->fetchAll();?><form method="post" style="text-align:right"><input type="hidden" name="csrf" value="<?=h($token)?>"><button name="logout">Sair</button></form><div class="grid"><div class="card"><small>Pedidos registrados</small><h2><?=$stats['orders']?></h2></div><div class="card"><small>Reservas recebidas</small><h2><?=$stats['reservations']?></h2></div><div class="card"><small>Receita confirmada</small><h2>R$ <?=number_format($stats['revenue']/100,2,',','.')?></h2></div></div><section class="section"><h2>Últimos pedidos</h2><div class="panel"><?php foreach($orders as $o):?><div class="line"><span>#<?=h($o['id'])?> · <?=h($o['customer_name'])?> <small><?=h($o['fulfillment'])?></small></span><span><?=h($o['status'])?> · <?=h($o['payment_status'])?> · R$ <?=number_format($o['total_cents']/100,2,',','.')?></span></div><?php endforeach;?></div></section><section class="section"><h2>Reservas recentes</h2><div class="panel"><?php foreach($reservations as $r):?><div class="line"><span>#<?=h($r['id'])?> · <?=h($r['customer_name'])?> · <?=h($r['guests'])?> pessoas</span><span><?=h($r['date'])?> <?=h($r['time'])?> · <?=h($r['status'])?></span></div><?php endforeach;?></div></section><p class="muted">Visualização inicial. Gestão de status, produtos e conciliação de pagamentos serão implementadas posteriormente.</p><?php endif;?></main></body></html>